    /** Move a claim to a new status; a change its status does not allow is refused, as is settling
     *  by the user who opened the claim, and an action the sheet's permission matrix does not allow the
     *  user's role. A clerk's settling of a claim whose due is above the sheet's
     *  clerk limit leaves it PENDING for a steward to approve (a due of n/a is within any limit; a
     *  steward settles anything). */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
        refuseIfClosed(sheetId, claim.getDate());
        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
        if (voidingSettled) {
            refuseUnlessSettledVoidable(sheetId, user, claim);
        } else if (!claim.getStatus().canBecome(next)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
        } else {
            settings.refuseUnlessPermitted(sheetId, user, ACTIONS.get(next),
                    "Your role may not " + ACTIONS.get(next) + " a claim on this sheet.");
        }
        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then.");
        }
        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who opened a claim cannot settle it.");
        }
        Person person = person(sheetId, claim.getPersonId());
        // Worked out while the claim is still open: settling freezes the due, its late charge included.
        BigDecimal dueNow = next == ClaimStatus.SETTLED ? due(sheetId, person, claim) : null;
        if (next == ClaimStatus.SETTLED) refuseIfUnproven(sheetId, claim, dueNow);
        if (next == ClaimStatus.SETTLED && isAboveClerkLimit(sheetId, user, dueNow)) next = ClaimStatus.PENDING;
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : claim.getNumber();
        claim.setStatus(next);
        if (next == ClaimStatus.OPEN) claim.setOpenedBy(user);
        // A voided claim keeps its number, which is never given to another claim.
        claim.setNumber(number);
        if (next == ClaimStatus.SETTLED) claim.setSettledDue(dueNow);
        logStatus(sheetId, user, person, claim);
        Claim saved = claims.saveAndFlush(claim);
        String event = EVENTS.get(next);
        if (next == ClaimStatus.SETTLED) {
            recordChange(event, user, person, saved, number, " due=" + text(saved.getSettledDue()));
            notifyWatchers(user, person, saved);
        } else if (voidingSettled) {
            recordChange(event, user, person, saved, number, " reversed=" + text(saved.getSettledDue()));
        } else {
            recordChange(event, user, person, saved, number, "");
        }
        rollup.recordChanges(user, before);
        return saved;
    }

    /** Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the
     *  claim counts in no total, is not overdue, cannot be settled and no statement binds it. Refused for
     *  a claim that is not OPEN, a date not after today, and a claim dated inside a closed period. */
    @Transactional
    public Claim defer(String sheetId, String user, long id, LocalDate until) {
        this.sheets = sheets;
    }

    /** Open the claims of these ids in list order: people in the order they were added, each person's
     *  claims newest first. So their numbers follow that order. An id not of the sheet is refused. */
    public Result open(String sheetId, String user, Collection<Long> ids) {
        return change(sheetId, user, ids, ClaimStatus.OPEN);
    }

    /** Settle the claims of these ids in list order, each by the rules of settling one: a claim left
     *  PENDING counts as settled, one that cannot be settled is refused. An id not of the sheet is refused. */
    public Result settle(String sheetId, String user, Collection<Long> ids) {
        return change(sheetId, user, ids, ClaimStatus.SETTLED);
    }

    private Result change(String sheetId, String user, Collection<Long> ids, ClaimStatus next) {
        Set<Long> selected = new LinkedHashSet<>(ids);
        if (settings.roleOf(sheetId, user) == Role.VIEWER) {
            return new Result(List.of(), selected.size()); // a viewer changes nothing: each is refused
        }
        if (sheets.isArchived(sheetId)) {
            return new Result(List.of(), selected.size()); // an archived sheet changes nothing: each is refused
        }
        List<Long> ordered = inListOrder(sheetId, selected);
        List<Claim> changed = new ArrayList<>();
        int refused = selected.size() - ordered.size();
        for (long id : ordered) {
            try {
                changed.add(service.changeStatus(sheetId, user, id, next));
            } catch (ResponseStatusException notChanged) {
                refused++;
            }
        }
        return new Result(changed, refused);
    }

    private List<Long> inListOrder(String sheetId, Set<Long> ids) {
        Map<Long, Integer> personOrder = new HashMap<>();
        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
        for (int i = 0; i < listed.size(); i++) personOrder.put(listed.get(i).getId(), i);
        return claims.findBySheetIdOrderByListedDesc(sheetId).stream()
                .filter(c -> ids.contains(c.getId()))
                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
                .map(Claim::getId)
                .toList();
    }
}

